import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';

export class BookStore {
  constructor(file) {
    this.file = file;
    this.books = [];
    this.loaded = false;
  }

  async load() {
    try {
      const raw = await readFile(this.file, 'utf8');
      this.books = JSON.parse(raw);
    } catch (err) {
      if (err.code !== 'ENOENT') throw err;
      this.books = [];
    }
    this.loaded = true;
    return this;
  }

  // Write to a temp file then rename so a crash mid-write can't leave a half-written JSON file.
  async save() {
    await mkdir(dirname(this.file), { recursive: true });
    const tmp = `${this.file}.tmp`;
    await writeFile(tmp, JSON.stringify(this.books, null, 2) + '\n');
    await rename(tmp, this.file);
  }

  all() {
    return this.books;
  }

  reading() {
    return this.books.filter((b) => !b.finishedAt);
  }

  finished() {
    return this.books
      .filter((b) => b.finishedAt)
      .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
  }

  get(id) {
    return this.books.find((b) => b.id === id) ?? null;
  }

  async add({ title, author, notes = '' }) {
    title = title?.trim();
    author = author?.trim();
    if (!title) throw new ValidationError('Title is required.');
    if (!author) throw new ValidationError('Author is required.');
    const book = {
      id: randomUUID(),
      title,
      author,
      notes: notes.trim(),
      startedAt: new Date().toISOString(),
      finishedAt: null,
    };
    this.books.push(book);
    await this.save();
    return book;
  }

  async finish(id) {
    const book = this.get(id);
    if (!book) return null;
    if (!book.finishedAt) {
      book.finishedAt = new Date().toISOString();
      await this.save();
    }
    return book;
  }

  async updateNotes(id, notes) {
    const book = this.get(id);
    if (!book) return null;
    book.notes = (notes ?? '').trim();
    await this.save();
    return book;
  }
}

export class ValidationError extends Error {}

