export function escape(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

const styles = `
  :root { color-scheme: light dark; }
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; }
  h1 a { color: inherit; text-decoration: none; }
  h2 { margin-top: 2rem; font-size: 1.1rem; text-transform: uppercase; letter-spacing: .05em; opacity: .7; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { padding: .6rem 0; border-bottom: 1px solid color-mix(in srgb, currentColor 15%, transparent); }
  ul.books li a { font-weight: 600; text-decoration: none; color: inherit; }
  ul.books li a:hover { text-decoration: underline; }
  .author, .meta { opacity: .7; }
  .empty { opacity: .6; font-style: italic; }
  form.add, form.notes { display: grid; gap: .6rem; margin-top: 1rem; }
  label { display: grid; gap: .2rem; font-size: .9rem; }
  input, textarea { font: inherit; padding: .4rem .5rem; border: 1px solid color-mix(in srgb, currentColor 30%, transparent); border-radius: 4px; background: transparent; color: inherit; }
  textarea { min-height: 6rem; }
  button { font: inherit; padding: .45rem .9rem; border-radius: 4px; border: 1px solid currentColor; background: transparent; color: inherit; cursor: pointer; justify-self: start; }
  button.primary { background: #2f6f4f; border-color: #2f6f4f; color: white; }
  .error { color: #b3261e; }
  .notes { white-space: pre-wrap; }
  .badge { font-size: .75rem; padding: .1rem .5rem; border-radius: 999px; border: 1px solid currentColor; margin-left: .5rem; vertical-align: middle; }
  .actions { display: flex; gap: .75rem; align-items: center; margin: 1.5rem 0; }
  .actions form { display: inline; }
  code.link { user-select: all; font-size: .9rem; }
`;

export function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>${styles}</style>
</head>
<body>
<h1><a href="/">Bookshelf</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const when = book.finishedAt
    ? `finished ${formatDate(book.finishedAt)}`
    : `started ${formatDate(book.startedAt)}`;
  return `<li>
    <a href="/books/${escape(book.id)}">${escape(book.title)}</a>
    <span class="author">by ${escape(book.author)}</span>
    <div class="meta">${when}</div>
  </li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="empty">${escape(emptyText)}</p>`;
  return `<ul class="books">${books.map(bookItem).join('')}</ul>`;
}

export function homePage({ reading, finished, error = null, values = {} }) {
  return layout(
    'Bookshelf',
    `
<h2>Currently reading</h2>
${bookList(reading, "You're not reading anything right now.")}

<h2>Finished</h2>
${bookList(finished, 'No finished books yet.')}

<h2>Add a book</h2>
<form class="add" method="post" action="/books">
  ${error ? `<p class="error">${escape(error)}</p>` : ''}
  <label>Title <input name="title" required value="${escape(values.title)}"></label>
  <label>Author <input name="author" required value="${escape(values.author)}"></label>
  <label>Notes <textarea name="notes">${escape(values.notes)}</textarea></label>
  <button class="primary" type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book, url) {
  const status = book.finishedAt
    ? `<span class="badge">Finished ${formatDate(book.finishedAt)}</span>`
    : `<span class="badge">Reading since ${formatDate(book.startedAt)}</span>`;
  const finishButton = book.finishedAt
    ? ''
    : `<form method="post" action="/books/${escape(book.id)}/finish">
         <button class="primary" type="submit">Mark as finished</button>
       </form>`;
  return layout(
    `${book.title} · Bookshelf`,
    `
<p><a href="/">← All books</a></p>
<h2 style="text-transform:none;opacity:1;font-size:1.6rem;margin-top:.5rem">${escape(book.title)} ${status}</h2>
<p class="author">by ${escape(book.author)}</p>

<div class="actions">
  ${finishButton}
  <span class="meta">Share: <code class="link">${escape(url)}</code></span>
</div>

<h2>Notes</h2>
${book.notes ? `<p class="notes">${escape(book.notes)}</p>` : '<p class="empty">No notes yet.</p>'}

<form class="notes" method="post" action="/books/${escape(book.id)}/notes">
  <label>Edit notes <textarea name="notes">${escape(book.notes)}</textarea></label>
  <button type="submit">Save notes</button>
</form>`,
  );
}

export function notFoundPage() {
  return layout('Not found · Bookshelf', `<p>That book doesn't exist. <a href="/">Back to all books</a>.</p>`);
}

