import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createServer } from 'node:http';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { BookStore } from '../src/store.mjs';
import { createApp } from '../src/app.mjs';

let dir;
let server;
let base;
let store;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'bookshelf-app-'));
  store = await new BookStore(join(dir, 'books.json')).load();
  server = createServer(createApp(store));
  await new Promise((done) => server.listen(0, '127.0.0.1', done));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((done) => server.close(done));
  await rm(dir, { recursive: true, force: true });
});

const post = (path, fields) =>
  fetch(base + path, {
    method: 'POST',
    redirect: 'manual',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields).toString(),
  });

describe('HTTP app', () => {
  it('shows empty states on the home page', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain("You're not reading anything right now.");
    expect(html).toContain('No finished books yet.');
    expect(html).toContain('<form class="add"');
  });

  it('adds a book from the form and redirects to its page', async () => {
    const res = await post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'Fear is the mind-killer.' });
    expect(res.status).toBe(303);
    const location = res.headers.get('location');
    expect(location).toMatch(/^\/books\/[0-9a-f-]+$/);

    const page = await (await fetch(base + location)).text();
    expect(page).toContain('Dune');
    expect(page).toContain('by Frank Herbert');
    expect(page).toContain('Fear is the mind-killer.');
    expect(page).toContain('Mark as finished');
    expect(page).toContain(`${base}${location}`);

    const home = await (await fetch(base + '/')).text();
    expect(home).toContain(`href="${location}"`);
  });

  it('re-renders the form with an error on invalid input', async () => {
    const res = await post('/books', { title: '', author: 'Someone', notes: 'kept' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Title is required.');
    expect(html).toContain('value="Someone"');
    expect(store.all()).toEqual([]);
  });

  it('marks a book finished and moves it to the finished list', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    const res = await post(`/books/${book.id}/finish`, {});
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);

    const page = await (await fetch(base + `/books/${book.id}`)).text();
    expect(page).toContain('Finished');
    expect(page).not.toContain('Mark as finished');

    const home = await (await fetch(base + '/')).text();
    expect(home.indexOf('Finished')).toBeLessThan(home.indexOf('Dune'));
    expect(home).toContain("You're not reading anything right now.");
  });

  it('updates notes from the book page', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    await post(`/books/${book.id}/notes`, { notes: 'New thoughts' });
    const page = await (await fetch(base + `/books/${book.id}`)).text();
    expect(page).toContain('New thoughts');
  });

  it('escapes HTML in user content', async () => {
    const book = await store.add({ title: '<script>alert(1)</script>', author: 'A & B' });
    const page = await (await fetch(base + `/books/${book.id}`)).text();
    expect(page).not.toContain('<script>alert(1)</script>');
    expect(page).toContain('&lt;script&gt;');
    expect(page).toContain('A &amp; B');
  });

  it('returns 404 for unknown books and routes', async () => {
    expect((await fetch(base + '/books/does-not-exist')).status).toBe(404);
    expect((await fetch(base + '/nope')).status).toBe(404);
  });
});

